import{_ as t,C as s,o as r,c as n,a5 as i,E as o}from"./chunks/framework.BwlBv862.js";const v=JSON.parse('{"title":"Trouver les préférences et les commandes clavier","description":"","frontmatter":{"title":"Trouver les préférences et les commandes clavier","docId":"user.preferences.index","translationKey":"user.preferences.index","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6790ab7171a90bda1df882c0f88626a5875da68bf4f624968b0e54815842030f","translationRevision":"fd118aea8302443fc3b89b7fc4c9a7b63de7133ed2049d3bfadad4034bc84745","order":10},"headers":[],"relativePath":"fr/user/preferences/index.md","filePath":"fr/user/preferences/index.md","lastUpdated":1794611623000}'),l={name:"fr/user/preferences/index.md"};function c(d,e,u,p,m,f){const a=s("DemoFrame");return r(),n("div",null,[e[0]||(e[0]=i('<h1 id="find-preferences-and-keyboard-controls" tabindex="-1">Trouver les préférences et les commandes clavier <a class="header-anchor" href="#find-preferences-and-keyboard-controls" aria-label="Permalink to &quot;Trouver les préférences et les commandes clavier {#find-preferences-and-keyboard-controls}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Définir la langue de l’application, trouver le bon espace de configuration et utiliser confortablement les commandes clavier prises en charge. La fenêtre de bureau doit être ouverte ; l’accès réseau est nécessaire uniquement pour le service configuré.</p><h2 id="find-the-relevant-setting" tabindex="-1">Trouver le paramètre concerné <a class="header-anchor" href="#find-the-relevant-setting" aria-label="Permalink to &quot;Trouver le paramètre concerné {#find-the-relevant-setting}&quot;">​</a></h2><ol><li>Ouvrez <strong>Settings → General</strong> pour choisir la langue de l’interface. Les choix actuels sont l’anglais (<code>en</code>), l’espagnol (<code>es</code>), le portugais (<code>pt</code>), le français (<code>fr</code>), le chinois simplifié (<code>zh</code>) et le japonais (<code>ja</code>). Choisir une langue ne modifie pas les identifiants d’événements TikTok ni les noms d’API des plugins.</li><li>Examinez les commandes de mise à jour dans General : canal, vérifications automatiques, notifications et vérification manuelle lorsqu’elle est prise en charge. Les vérifications automatiques sont facultatives. La disponibilité des mises à jour signées dépend de la configuration de signature publiée de la compilation.</li><li>Utilisez <strong>Account</strong> pour l’identité Cloud et ses diagnostics. Utilisez <strong>Collaboration</strong> pour configurer l’accès du propriétaire, et <strong>Teams</strong> lorsque l’hôte expose cette capacité.</li><li>Ouvrez <strong>Plugins</strong> pour les préférences communes aux plugins et les volets Settings/Connection de chaque plugin. Les identifiants du service d’un plugin n’appartiennent pas aux paramètres General.</li><li>Ouvrez <strong>Automations → Variables</strong> pour les valeurs d’exécution partagées, <strong>Points</strong> pour les règles d’attribution et <strong>Overlays</strong> pour la conception des widgets. Ces espaces de configuration sont volontairement placés à côté des fonctionnalités concernées.</li></ol><p>L’installation automatique est expérimentale et désactivée par les conditions de compilation du processus de publication actuel. Une préférence visible de vérification automatique ne promet pas une installation automatique. Utilisez la <a href="./../updates.html">procédure de mise à jour</a> documentée et faites une <a href="./backups.html">sauvegarde</a> avant tout changement de version.</p><h2 id="use-supported-keyboard-controls" tabindex="-1">Utiliser les commandes clavier prises en charge <a class="header-anchor" href="#use-supported-keyboard-controls" aria-label="Permalink to &quot;Utiliser les commandes clavier prises en charge {#use-supported-keyboard-controls}&quot;">​</a></h2><p>Utilisez Tab et Shift+Tab pour déplacer le focus entre les commandes ordinaires, et Entrée/Espace pour activer les boutons ciblés. Dans l’inspecteur de conception d’incrustation, Ctrl/Meta+Z annule et Ctrl/Meta+Shift+Z ou Ctrl/Meta+Y rétablit. Les champs texte conservent leur propre annulation. Ce sont des raccourcis d’éditeur, pas des raccourcis globaux d’automatisation.</p><p>Échap ferme le volet de navigation étroit si une autre commande ne l’a pas consommé. Les boîtes de dialogue et éditeurs peuvent gérer Échap eux-mêmes, y compris avec une demande concernant les modifications non enregistrées. L’automatisation par raccourcis globaux nécessite un plugin compatible installé et les capacités annoncées de son moteur.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Résultat attendu, état et récupération <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Résultat attendu, état et récupération {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Ces paramètres et interactions clavier locales sont disponibles ; aucune validation complète d’accessibilité ou de plateforme n’est affirmée. Préférez des boutons libellés, des tailles de fenêtre lisibles et le défilement du flux en pause lorsque le mouvement distrait. Si un paramètre semble absent, vérifiez sa page propriétaire et la capacité de l’hôte avant de réinitialiser les données. Consultez le <a href="./troubleshooting.html">dépannage</a> pour les commandes indisponibles et la <a href="./faq.html">FAQ</a> pour les distinctions courantes.</p>',11)),o(a,{scenario:"settings",locale:"fr",title:"Démo : paramètres"})])}const b=t(l,[["render",c]]);export{v as __pageData,b as default};
